#include <omp.h>
#include <vector>
#include <stdexcept>
#include <cstddef>
#include <limits>

void axpy(double alpha, std::vector<double> const& x, std::vector<double> const& y, std::vector<double> &z) {
    if (x.size() != y.size()) {
        throw std::invalid_argument("axpy: x and y must have the same size");
    }

    if (x.size() > static_cast<std::size_t>(std::numeric_limits<std::ptrdiff_t>::max())) {
        throw std::overflow_error("axpy: vector size exceeds supported OpenMP loop index range");
    }

    const std::size_t n = x.size();
    if (z.size() != n) {
        z.resize(n);
    }

    const std::ptrdiff_t n_omp = static_cast<std::ptrdiff_t>(n);

    #pragma omp parallel for default(none) shared(x, y, z, alpha, n_omp) schedule(static)
    for (std::ptrdiff_t i = 0; i < n_omp; ++i) {
        const std::size_t idx = static_cast<std::size_t>(i);
        z[idx] = alpha * x[idx] + y[idx];
    }
}
